<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('POST');require_csrf();$user=require_login();$in=json_input();$current=(string)($in['current_password']??'');$new=(string)($in['new_password']??'');if(strlen($new)<8)json_response(['ok'=>false,'error'=>'La nueva contraseña debe tener al menos 8 caracteres'],400);$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$uid=(int)$user['user_id'];$st=$db->prepare("SELECT password_hash FROM usuario WHERE usuario_id=?");$st->bind_param('i',$uid);$st->execute();$row=$st->get_result()->fetch_assoc();$st->close();if(!$row||!password_verify($current,(string)$row['password_hash'])){$db->close();json_response(['ok'=>false,'error'=>'La contraseña actual no es correcta'],401);}$hash=password_hash($new,PASSWORD_DEFAULT);$st=$db->prepare("UPDATE usuario SET password_hash=?,requiere_cambio_password=0 WHERE usuario_id=?");$st->bind_param('si',$hash,$uid);$st->execute();$st->close();audit_log($db,$uid,'PASSWORD_CAMBIO','USUARIO',$uid,'Cambio de contraseña');$db->close();json_response(['ok'=>true]);
